(() => {
 const button=document.createElement('button');button.id='lessonVoiceToggle';button.type='button';button.hidden=true;document.querySelector('.room-actions').append(button);
 const hint=document.createElement('p');hint.id='lessonVoicePolicy';hint.className='settings-help';hint.setAttribute('role','status');document.querySelector('.livebox').prepend(hint);
 const usage=document.createElement('details');usage.id='lessonUsage';usage.hidden=true;usage.innerHTML='<summary>Consumo da tradução</summary><p id="lessonUsageStatus" role="status">O valor aparece após a conclusão das sessões de voz.</p><button type="button" id="refreshLessonUsage">Atualizar consumo</button><small>Valores em dólar, informados pela Soniox para sessões finalizadas desta sala. Sessões em andamento ainda não entram no total. Silêncio com o serviço conectado pode ser cobrado.</small>';document.querySelector('.livebox').append(usage);
 let hooks={},current,busy=false,timer;
 async function refresh(){if(!current||current.you.role!=='teacher'||!usage.open)return;const control=document.getElementById('refreshLessonUsage');control.disabled=true;try{const data=await hooks.usage();if(data.available===false)throw Error(data.message||'Consumo indisponível no momento.');const amount=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD',minimumFractionDigits:4,maximumFractionDigits:6}).format(data.costUsd);document.getElementById('lessonUsageStatus').textContent='Total confirmado: '+amount+' · '+data.sessions+' sessão(ões) · '+Math.round(data.audioMs/60000)+' min de áudio.'+(data.partial?' Consulta parcial; confira o painel Soniox.':'');}catch(error){document.getElementById('lessonUsageStatus').textContent=error.message||'Não foi possível consultar o consumo.';}finally{control.disabled=false;}}
 usage.addEventListener('toggle',()=>{clearInterval(timer);if(usage.open){refresh();timer=setInterval(refresh,30000);}});document.getElementById('refreshLessonUsage').onclick=refresh;
 button.onclick=async()=>{if(busy||current?.you.role!=='teacher')return;busy=true;button.disabled=true;try{await hooks.save(current.lesson?.captionsEnabled===false);}catch(error){hint.textContent=error.message||'Não foi possível alterar a tradução.';}finally{busy=false;button.disabled=false;}};
 window.lessonVoice={configure:value=>hooks=value,sync(state){current=state;const on=state.lesson?.captionsEnabled!==false,teacher=state.you.role==='teacher';button.hidden=!teacher||state.you.status!=='accepted'||state.ended;button.disabled=busy||state.ending;button.textContent=on?'Tradução ligada':'Tradução desligada';button.setAttribute('aria-pressed',String(on));button.title=on?'Desligar transcrição e tradução pagas nesta sala':'Ativar transcrição e tradução nesta sala';usage.hidden=!teacher;hint.textContent=on?'Ligue o microfone para transcrever e traduzir.':'A professora desligou a transcrição e a tradução. O microfone continua disponível para conversar.';},close(){clearInterval(timer);usage.open=false;}};
})();
